class Solution:
    def maxAverageOfPath(self, matrix: List[List[int]]) -> float:

        # Initialize the maximum path sum to negative infinity
        max_path_sum = float('-inf')

        # Iterate through each cell in the matrix
        for i in range(len(matrix)):
            for j in range(len(matrix[0])):
                # If the cell is not visited, calculate the path sum
                if matrix[i][j] == 0:
                    path_sum = 0

                    # Check if the cell is the starting cell
                    if i == 0 and j == 0:
                        path_sum = matrix[i][j]
                    # Check if the cell is the ending cell
                    elif i == len(matrix) - 1 and j == len(matrix[0]) - 1:
                        path_sum = matrix[i][j]
                    # If the cell is not visited, calculate the path sum
                    else:
                        path_sum = matrix[i][j] + matrix[i][j - 1] + matrix[i][j + 1] - matrix[i][j - 1] - matrix[i][j + 1]

                    # Update the maximum path sum if the current path sum is greater
                    max_path_sum = max(max_path_sum, path_sum)

        # Return the maximum path sum
        return max_path_sum

