def find_sum(nums):
    """
    :type nums: List[int]
    :rtype: int
    """
    # Create a dictionary to store the frequency of each element
    frequency = {}

    # Iterate through the list and update the frequency of each element
    for num in nums:
        if num in frequency:
            frequency[num] += 1
        else:
            frequency[num] = 1

    # Initialize the sum of non-repeated elements
    sum_of_non_repeated = 0

    # Iterate through the frequency dictionary
    for num, freq in frequency.items():
        # If the frequency of an element is 1, it means it's non-repeated
        if freq == 1:
            sum_of_non_repeated += num

    return sum_of_non_repeated

