    def isPerfectSquare(self, n):
        """
        :type n: int
        :rtype: bool
        """
        if n == 1:
            return True

        left = 1
        right = n

        while left <= right:
            mid = left + (right - left) // 2
            if mid * mid == n:
                return True
            elif mid * mid < n:
                left = mid + 1
            else:
                right = mid - 1

        return False

